// Long tasks block input response
// Break up long tasks:
function processItems(items) {
  return new Promise(resolve => {
    function chunk(i) {
      if (i >= items.length) return resolve();
      items[i].process();
      setTimeout(() => chunk(i + 1), 0);
    }
    chunk(0);
  });
}

const entries = performance.getEntriesByType('resource');
const slowResources = entries.filter(e => e.duration > 1000);
slowResources.forEach(e => console.log(e.name, e.duration));

window.addEventListener('load', () => {
  const [nav] = performance.getEntriesByType('navigation');
  console.log('TTFB:', nav.responseStart - nav.requestStart);
  console.log('DOM interactive:', nav.domInteractive);
  console.log('Load:', nav.loadEventEnd);
});

const observer = new PerformanceObserver(list => {
  let cls = 0;
  list.getEntries().forEach(entry => {
    if (!entry.hadRecentInput) cls += entry.value;
  });
  console.log('CLS so far:', cls);
});
observer.observe({ type: 'layout-shift', buffered: true });

new PerformanceObserver(list => {
  list.getEntries().forEach(entry => {
    if (entry.duration > 50) {
      console.warn('Long animation frame:', entry.duration, entry.scripts);
    }
  });
}).observe({ type: 'long-animation-frame', buffered: true });

